def material_con_lo_que_falta(material, faltantes, archivo, raiz):
    """El equipo viene en ayuda de la IA: pide lo que necesita y aqui esta.

    Cuando al material le falta una pieza, en vez de morir la vuelta, se le pide
    al mostrador (arnes/mostrador.py) que traiga SOLO lo pedido, por su nombre y
    entero, y se pega al final del material. Asi el codigo no engorde: solo se
    anade lo que la tarea nombro y no venia.

    Recibe el material, la lista de frases de lo que falta, el nombre del archivo
    que la tarea nombra y la carpeta del proyecto. Devuelve el material con lo
    atendido pegado, o el material TAL CUAL si no hay nada util. NUNCA revienta.
    """
    try:
        if not material or not faltantes:
            return material
        if not isinstance(faltantes, (list, tuple)):
            return material
        peticiones = []
        for frase in faltantes:
            try:
                texto = str(frase)
            except Exception:
                continue
            for nombre in _nombres_de_funcion_del_texto(texto):
                peticiones.append({"archivo": archivo, "nombre": nombre})
        if not peticiones:
            return material
        from arnes.mostrador import atender
        traido = atender(peticiones, raiz)
        if not traido or not str(traido).strip():
            return material
        if str(traido).strip() == "NO_ESTA":
            return material
        return (str(material)
                + "\n\nLO QUE FALTABA, ATENDIDO POR EL MOSTRADOR\n"
                + str(traido))
    except Exception:
        return material


